import{_ as a,o as r,c as e,ag as d}from"./chunks/framework.Aev9KvMf.js";const c=JSON.parse('{"title":"医保药品目录查询 · 这个药能不能报","description":"医保药品目录官方查询教程：国家医保服务平台核对这个药在不在目录内、是甲类还是乙类，配合定点机构查询用。","frontmatter":{"title":"医保药品目录查询 · 这个药能不能报","issuer":"国家医疗保障局","source_tier":"一级来源","version":"—","published":"—","source_url":"https://fuwu.nhsa.gov.cn/","status":"现行服务","tags":["官方查询","医保","药品目录","报销"],"type":"查询页","reviewed":false,"description":"医保药品目录官方查询教程：国家医保服务平台核对这个药在不在目录内、是甲类还是乙类，配合定点机构查询用。"},"headers":[],"relativePath":"query/yibao-drug.md","filePath":"query/yibao-drug.md"}'),o={name:"query/yibao-drug.md"};function h(l,t,n,s,i,u){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="医保药品目录查询-·-这个药能不能报" tabindex="-1">医保药品目录查询 · 这个药能不能报 <a class="header-anchor" href="#医保药品目录查询-·-这个药能不能报" aria-label="Permalink to &quot;医保药品目录查询 · 这个药能不能报&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 依据官方平台公开信息整理，查询步骤请以平台实际页面为准；入口改版时以国家医保局官网为准。</p></div><blockquote><p><strong>官方入口</strong>：国家医疗保障局<a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">国家医保服务平台</a>（&quot;药品目录查询&quot;模块；App 同步提供）。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>药品在不在<strong>国家医保药品目录</strong>、属于<strong>甲类</strong>（全额纳入报销）还是<strong>乙类</strong>（部分自付先扣），直接决定报销金额。目录每年调整（谈判新增抗癌药、慢病用药等）——查最新版，别信&quot;这药报不了&quot;的口头说法。</p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>打开 <a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">国家医保服务平台</a>（或 App → 药品目录查询）</td></tr><tr><td>2</td><td>输入药品通用名（化学名，不用商品名）</td></tr><tr><td>3</td><td>看结果：<strong>是否在目录内、甲类/乙类、限定支付范围</strong>（有些药只有特定病情才报）</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>目录内·甲类</td><td>全额纳入报销计算（<a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">国家医保服务平台</a>）</td></tr><tr><td>目录内·乙类</td><td>先按比例自付一部分，其余纳入报销</td></tr><tr><td>目录内但有限定支付范围</td><td>符合限定病情才报，需医生诊断佐证</td></tr><tr><td>目录外</td><td>医保不报（部分商业保险可报）</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;自费药更高级，医保的不好&quot;</td><td>目录内不乏最新谈判药（抗癌、慢病大品种），以查询结果为准</td></tr><tr><td>【本站提示】配合<a href="/SageRelay/query/yibao.html">医保定点机构查询</a>一起用：定点 + 目录内 + 备案完成 = 报销三件套</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li><a href="/SageRelay/query/yibao.html">医保定点机构查询</a></li><li><a href="/SageRelay/query/hospital-doctor.html">医疗机构与执业医师查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>国家医疗保障局国家医保服务平台（一级来源）</td></tr><tr><td>入口</td><td><a href="https://fuwu.nhsa.gov.cn/" target="_blank" rel="noreferrer">fuwu.nhsa.gov.cn</a>（入口以国家医保局官网为准）</td></tr></tbody></table>',15)])])}const f=a(o,[["render",h]]);export{c as __pageData,f as default};
